from dataclasses import dataclass, field
from typing import Callable, Iterable, Sequence

Metric = Callable[[Sequence[object], Sequence[object]], float]


def accuracy(labels: Sequence[object], predictions: Sequence[object]) -> float:
    """Return the fraction of matching labels and predictions."""
    if len(labels) != len(predictions):
        raise ValueError("labels and predictions must have the same length")
    if not labels:
        return 0.0
    correct = sum(1 for label, prediction in zip(labels, predictions) if label == prediction)
    return correct / len(labels)


@dataclass
class VisionLearner:
    """Small learner object used by RetinaPy readiness checks.

    The real training workers only need learner metadata at this stage, so this
    compatibility object mirrors the attributes consumed by RetinaPy without
    starting a full fastai-style training pipeline.
    """

    arch: str
    n_out: int
    metrics: list[Metric] = field(default_factory=list)
    framework: str = "fatai"


def vision_learner(*, arch: str, n_out: int, metrics: Iterable[Metric] | None = None, **_: object) -> VisionLearner:
    """Construct a lightweight vision learner metadata object."""
    if n_out <= 0:
        raise ValueError("n_out must be positive")
    return VisionLearner(arch=arch, n_out=n_out, metrics=list(metrics or []))
